input.command:
cd /home/binoui && python3 - <<'EOF'
import json, os
p = os.path.expanduser("~/.claude.json")
try:
    d = json.load(open(p))
except Exception as e:
    print("err", e); raise SystemExit
def show(name, servers):
    if servers:
        print(f"[{name}] mcpServers:", {k: {kk: vv for kk, vv in v.items() if kk not in ('env','headers')} for k, v in servers.items()})
show("user", d.get("mcpServers"))
for proj, cfg in (d.get("projects") or {}).items():
    s = cfg.get("mcpServers")
    if s:
        show(proj, s)
EOF
