input.command:
cd /tmp && blender -b --factory-startup --python-expr "
import bpy
cp = bpy.context.preferences.addons['cycles'].preferences
for kind in ('ONEAPI','CUDA','OPTIX','HIP'):
    try:
        print('CYCLES', kind, [d.name for d in cp.get_devices_for_type(kind) if d.type != 'CPU'] or 'no GPU devices')
    except Exception as e:
        print('CYCLES', kind, 'unavailable:', e)
print('CYCLES CPU', [d.name for d in cp.get_devices_for_type('NONE')][:1] if hasattr(cp,'get_devices_for_type') else '')
" 2>&1 | grep -E "^CYCLES|oneAPI|Level Zero|level_zero|ze_" | head -12

